//------------------------------------------------------------------------------
// test_decimal.cpp -- System.Decimal arithmetic (T1) runtime unit tests.
// net48 oracle values (the project's semantic baseline): every expected
// lo/mid/hi/flags 4-dword pattern below was generated by a .NET Framework 4.8
// probe (decimal.GetBits) and cross-checked against decimal-domain.md T1.
//
// Coverage, mirroring decimal.h:
//   1. add/sub: 0.1m+0.2m == 0.3m (user oracle), 1m-0.1m, 0.1m-0.2m
//      (negative zero kept), maxvalue+0m, -1.5m+1.5m.
//   2. mul: 1.5m*2m, 0.1m*0.2m, -2.5m*-4m, big mantissa*1e6 (scale 9).
//   3. div: 100m/7m (user oracle), 1m/7m, 10m/4m, 1m/3m, 2m/3m, -1m/3m,
//      1m/2m, 1m/1000m, 1000m/1m.
//   4. rem: 10m%3m, -10m%3m, 10m%-3m, 0.5m%0.3m.
//   5. compare/equals/negate: scale-insensitive equality, sign handling.
//   6. round (modes 0..4): ToEven/AwayFromZero half cases, decimals param,
//      maxvalue, scale-28 edge; mode/decimals argument validation.
//   7. truncate/floor/ceiling: positive/negative truncation semantics.
//   8. ctors: int/uint/long/ulong, int.MinValue, 5-arg literal shape
//      (incl. negative + scale 28), bad scale -> ArgumentOutOfRangeException.
//   9. ToInt32/64/UInt32/64 truncation incl. boundary values; overflow paths.
//  10. GetHashCode: scale canonicalization (1m == 1.00m), zero -> 0.
//  11. Overflow/divide-by-zero exception paths (net48 types).
//
// CALL SHAPE (T3 result-slot contract, MethodMap.Decimal.cs:23-35): every
// decimal-PRODUCING icall takes the result slot FIRST -- fn(t, a, b). The
// converted blocks above pass the accumulator slot twice (fn(&a, &a, &b) --
// the legacy in-place shape, now aliasing result==input); section 12
// exercises the strict non-aliasing emitter shape with input-preservation
// checks.
//
// Like the other runtime tests: plain executable, minimal assertion harness
// (Expect prints FAIL and bumps the counter; non-zero exit on failure).
//------------------------------------------------------------------------------

#include "decimal.h"
#include "il2cpp_exception.h"

#include <cstdint>
#include <cstdio>
#include <cstring>

namespace {

using il2cpp::runtime::Il2CppDecimal;
using il2cpp::runtime::icall_decimal_add;
using il2cpp::runtime::icall_decimal_sub;
using il2cpp::runtime::icall_decimal_mul;
using il2cpp::runtime::icall_decimal_div;
using il2cpp::runtime::icall_decimal_rem;
using il2cpp::runtime::icall_decimal_compare;
using il2cpp::runtime::icall_decimal_equals;
using il2cpp::runtime::icall_decimal_negate;
using il2cpp::runtime::icall_decimal_round;
using il2cpp::runtime::icall_decimal_truncate;
using il2cpp::runtime::icall_decimal_floor;
using il2cpp::runtime::icall_decimal_ceiling;
using il2cpp::runtime::icall_decimal_ctor_int32;
using il2cpp::runtime::icall_decimal_ctor_uint32;
using il2cpp::runtime::icall_decimal_ctor_int64;
using il2cpp::runtime::icall_decimal_ctor_uint64;
using il2cpp::runtime::icall_decimal_ctor_5;
using il2cpp::runtime::icall_decimal_to_int32;
using il2cpp::runtime::icall_decimal_to_int64;
using il2cpp::runtime::icall_decimal_to_uint32;
using il2cpp::runtime::icall_decimal_to_uint64;
using il2cpp::runtime::icall_decimal_get_hash_code;

int g_failures = 0;

void Expect(bool condition, const char* what)
{
    if (!condition)
    {
        std::printf("FAIL: %s\n", what);
        ++g_failures;
    }
}

// Build a decimal from mantissa+scale+sign (net48 value semantics, T2 style).
Il2CppDecimal MakeDec(uint64_t lo64, int scale, bool negative = false)
{
    Il2CppDecimal d;
    d.flags = (negative ? 0x80000000 : 0) | (scale << 16);
    d.hi32 = 0;
    d.lo64 = lo64;
    return d;
}

// Build a decimal from lo64 + explicit hi32 (for >64-bit mantissas).
Il2CppDecimal MakeDec(uint64_t lo64, uint32_t hi32, int scale, bool negative)
{
    Il2CppDecimal d;
    d.flags = (negative ? 0x80000000 : 0) | (scale << 16);
    d.hi32 = hi32;
    d.lo64 = lo64;
    return d;
}

// Compare a decimal's raw 4 dwords against the net48 oracle (GetBits order).
void ExpectBits(const char* what, const Il2CppDecimal& d, uint32_t lo,
                uint32_t mid, uint32_t hi, uint32_t flags)
{
    const uint32_t dLo = (uint32_t)d.lo64;
    const uint32_t dMid = (uint32_t)(d.lo64 >> 32);
    bool ok = dLo == lo && dMid == mid && d.hi32 == hi &&
              (uint32_t)d.flags == flags;
    if (!ok)
    {
        std::printf("FAIL: %s (got lo=%08X mid=%08X hi=%08X flags=%08X)\n",
                    what, dLo, dMid, d.hi32, (uint32_t)d.flags);
        ++g_failures;
    }
}

// Throws-expectation (type-tag prefix match on the DotNetException chain).
void ExpectThrows(const char* what, const char* typeTag,
                  void (*fn)(Il2CppDecimal&, Il2CppDecimal&))
{
    Il2CppDecimal a = MakeDec(1, 0);
    Il2CppDecimal b = MakeDec(1, 0);
    bool caught = false;
    try
    {
        fn(a, b);
    }
    catch (const il2cpp::DotNetException& e)
    {
        caught = true;
        Expect(std::strncmp(e.type_name(), typeTag, std::strlen(typeTag)) == 0,
               "exception type tag matches the managed type");
    }
    catch (...)
    {
        caught = true;
        Expect(false, "wrong exception carrier type (not DotNetException)");
    }
    Expect(caught, what);
}

} // namespace

int main()
{
    // --- 1. add (net48 oracle; user case first) ---
    {
        Il2CppDecimal a = MakeDec(1, 1);      // 0.1m
        Il2CppDecimal b = MakeDec(2, 1);      // 0.2m
        icall_decimal_add(&a, &a, &b);
        ExpectBits("0.1m + 0.2m == 0.3m", a, 3, 0, 0, 0x00010000);
    }
    {
        Il2CppDecimal a = MakeDec(1, 0);      // 1m
        Il2CppDecimal b = MakeDec(1, 1);      // 0.1m
        icall_decimal_sub(&a, &a, &b);
        ExpectBits("1m - 0.1m == 0.9m", a, 9, 0, 0, 0x00010000);
    }
    {
        Il2CppDecimal a = MakeDec(1, 1);      // 0.1m
        Il2CppDecimal b = MakeDec(2, 1);      // 0.2m
        icall_decimal_sub(&a, &a, &b);
        ExpectBits("0.1m - 0.2m == -0.1m", a, 1, 0, 0, 0x80010000);
    }
    {
        Il2CppDecimal a = MakeDec(0xFFFFFFFFFFFFFFFFull, 0xFFFFFFFF, 0, false);
        Il2CppDecimal b = MakeDec(0, 0);
        icall_decimal_add(&a, &a, &b);
        ExpectBits("maxvalue + 0m == maxvalue", a, 0xFFFFFFFF, 0xFFFFFFFF,
                   0xFFFFFFFF, 0);
    }
    {
        Il2CppDecimal a = MakeDec(15, 1, true); // -1.5m
        Il2CppDecimal b = MakeDec(15, 1);       // 1.5m
        icall_decimal_add(&a, &a, &b);
        // net48: -1.5m + 1.5m == 0.0 (negative zero kept: sign + scale 1).
        ExpectBits("-1.5m + 1.5m == 0.0 (neg zero)", a, 0, 0, 0, 0x80010000);
    }

    // --- 2. mul (net48 oracle) ---
    {
        Il2CppDecimal a = MakeDec(15, 1);   // 1.5m
        Il2CppDecimal b = MakeDec(2, 0);    // 2m
        icall_decimal_mul(&a, &a, &b);
        ExpectBits("1.5m * 2m == 3.0m", a, 0x1E, 0, 0, 0x00010000);
    }
    {
        Il2CppDecimal a = MakeDec(1, 1);    // 0.1m
        Il2CppDecimal b = MakeDec(2, 1);    // 0.2m
        icall_decimal_mul(&a, &a, &b);
        ExpectBits("0.1m * 0.2m == 0.02m", a, 2, 0, 0, 0x00020000);
    }
    {
        Il2CppDecimal a = MakeDec(25, 1, true); // -2.5m
        Il2CppDecimal b = MakeDec(4, 0, true);  // -4m
        icall_decimal_mul(&a, &a, &b);
        ExpectBits("-2.5m * -4m == 10.0m", a, 0x64, 0, 0, 0x00010000);
    }
    {
        // 123456789.123456789m * 1000000m -> 123456789123456.789000000
        Il2CppDecimal a = MakeDec(0x01B69B4BACD05F15ull, 0, 9, false);
        Il2CppDecimal b = MakeDec(1000000, 0);
        icall_decimal_mul(&a, &a, &b);
        ExpectBits("123456789.123456789m * 1e6", a, 0x7ED62F40, 0x9B1F75AE,
                   0x00001A24, 0x00090000);
    }

    // --- 3. div (net48 oracle; user cases first) ---
    {
        Il2CppDecimal a = MakeDec(100, 0);  // 100m
        Il2CppDecimal b = MakeDec(7, 0);    // 7m
        icall_decimal_div(&a, &a, &b);
        ExpectBits("100m / 7m", a, 0xCDB6DB6E, 0x3434DED3, 0x2E28DDAB,
                   0x001B0000); // 14.285714285714285714285714286
    }
    {
        Il2CppDecimal a = MakeDec(100, 0);
        Il2CppDecimal b = MakeDec(7, 0);
        icall_decimal_div(&a, &a, &b);
        icall_decimal_mul(&a, &a, &b);
        // net48: (100m/7m)*7m == 100m numerically (scale 26) -- verified
        // on .NET Framework 4.8; the decimal == comparison ignores scale.
        ExpectBits("(100m/7m)*7m == 100m", a, 0x10000000, 0x3E250261,
                   0x204FCE5E, 0x001A0000); // 100.00000000000000000000000000
    }
    {
        Il2CppDecimal a = MakeDec(1, 0);    // 1m
        Il2CppDecimal b = MakeDec(7, 0);    // 7m
        icall_decimal_div(&a, &a, &b);
        ExpectBits("1m / 7m", a, 0x94924925, 0x5205497B, 0x049DAFC4,
                   0x001C0000); // 0.1428571428571428571428571429
    }
    {
        Il2CppDecimal a = MakeDec(10, 0);
        Il2CppDecimal b = MakeDec(4, 0);
        icall_decimal_div(&a, &a, &b);
        ExpectBits("10m / 4m == 2.5m", a, 0x19, 0, 0, 0x00010000);
    }
    {
        Il2CppDecimal a = MakeDec(1, 0);
        Il2CppDecimal b = MakeDec(3, 0);
        icall_decimal_div(&a, &a, &b);
        ExpectBits("1m / 3m", a, 0x05555555, 0x14B700CB, 0x0AC544CA,
                   0x001C0000); // 0.3333333333333333333333333333
    }
    {
        Il2CppDecimal a = MakeDec(2, 0);
        Il2CppDecimal b = MakeDec(3, 0);
        icall_decimal_div(&a, &a, &b);
        ExpectBits("2m / 3m", a, 0x0AAAAAAB, 0x296E0196, 0x158A8994,
                   0x001C0000); // 0.6666666666666666666666666667
    }
    {
        Il2CppDecimal a = MakeDec(1, 0, true); // -1m
        Il2CppDecimal b = MakeDec(3, 0);       // 3m
        icall_decimal_div(&a, &a, &b);
        ExpectBits("-1m / 3m", a, 0x05555555, 0x14B700CB, 0x0AC544CA,
                   0x801C0000); // -0.3333333333333333333333333333
    }
    {
        Il2CppDecimal a = MakeDec(1, 0);
        Il2CppDecimal b = MakeDec(2, 0);
        icall_decimal_div(&a, &a, &b);
        ExpectBits("1m / 2m == 0.5m", a, 5, 0, 0, 0x00010000);
    }
    // scale-difference paths (net48 oracle)
    {
        Il2CppDecimal a = MakeDec(1, 0);
        Il2CppDecimal b = MakeDec(1000, 0);
        icall_decimal_div(&a, &a, &b);
        ExpectBits("1m / 1000m == 0.001m", a, 1, 0, 0, 0x00030000);
    }
    {
        Il2CppDecimal a = MakeDec(1000, 0);
        Il2CppDecimal b = MakeDec(1, 0);
        icall_decimal_div(&a, &a, &b);
        ExpectBits("1000m / 1m == 1000m", a, 0x3E8, 0, 0, 0);
    }
    {
        // net48: maxvalue / 0.1m overflows (result would need scale -1).
        ExpectThrows("maxvalue / 0.1m -> OverflowException",
                     "System.OverflowException",
                     [](Il2CppDecimal& x, Il2CppDecimal& y) {
                         x = MakeDec(0xFFFFFFFFFFFFFFFFull, 0xFFFFFFFF, 0, false);
                         y = MakeDec(1, 1); // 0.1m
                         icall_decimal_div(&x, &x, &y);
                     });
    }

    // --- 4. rem (net48 oracle; sign follows dividend) ---
    {
        Il2CppDecimal a = MakeDec(10, 0);
        Il2CppDecimal b = MakeDec(3, 0);
        icall_decimal_rem(&a, &a, &b);
        ExpectBits("10m % 3m == 1m", a, 1, 0, 0, 0);
    }
    {
        Il2CppDecimal a = MakeDec(10, 0, true); // -10m
        Il2CppDecimal b = MakeDec(3, 0);        // 3m
        icall_decimal_rem(&a, &a, &b);
        ExpectBits("-10m % 3m == -1m", a, 1, 0, 0, 0x80000000);
    }
    {
        Il2CppDecimal a = MakeDec(10, 0);        // 10m
        Il2CppDecimal b = MakeDec(3, 0, true);   // -3m
        icall_decimal_rem(&a, &a, &b);
        ExpectBits("10m % -3m == 1m", a, 1, 0, 0, 0);
    }
    {
        Il2CppDecimal a = MakeDec(5, 1);    // 0.5m
        Il2CppDecimal b = MakeDec(3, 1);    // 0.3m
        icall_decimal_rem(&a, &a, &b);
        ExpectBits("0.5m % 0.3m == 0.2m", a, 2, 0, 0, 0x00010000);
    }

    // --- 5. compare / equals / negate ---
    {
        Il2CppDecimal a = MakeDec(10, 1);       // 1.0m
        Il2CppDecimal b = MakeDec(100, 2);      // 1.00m
        Expect(icall_decimal_compare(&a, &b) == 0, "Compare(1.0m, 1.00m) == 0");
        Expect(icall_decimal_equals(&a, &b), "1.0m == 1.00m (scale ignored)");
    }
    {
        Il2CppDecimal a = MakeDec(1, 0);
        Il2CppDecimal b = MakeDec(2, 0);
        Expect(icall_decimal_compare(&a, &b) == -1, "Compare(1m, 2m) == -1");
        Expect(icall_decimal_compare(&b, &a) == 1, "Compare(2m, 1m) == 1");
        Expect(!icall_decimal_equals(&a, &b), "1m != 2m");
    }
    {
        Il2CppDecimal a = MakeDec(35, 1, true); // -3.5m
        Il2CppDecimal b = MakeDec(35, 1);       // 3.5m
        Expect(icall_decimal_compare(&a, &b) == -1, "Compare(-3.5m, 3.5m) == -1");
    }
    {
        Il2CppDecimal a = MakeDec(15, 1, true); // -1.5m
        icall_decimal_negate(&a, &a);
        ExpectBits("Negate(-1.5m) == 1.5m", a, 15, 0, 0, 0x00010000);
        icall_decimal_negate(&a, &a);
        ExpectBits("Negate(1.5m) == -1.5m", a, 15, 0, 0, 0x80010000);
    }
    {
        Il2CppDecimal a = MakeDec(0, 0);
        Il2CppDecimal b = MakeDec(0, 0);
        Expect(icall_decimal_compare(&a, &b) == 0, "Compare(0, 0) == 0");
        Expect(icall_decimal_equals(&a, &b), "0 == 0");
    }

    // --- 6. round (net48 oracle; modes 0/1 verified directly; modes 2..4
    //         are the netcore MidpointRounding values net48 REJECTS through
    //         Round (ArgumentException, D-DR-1 fix); their ToZero/
    //         ToNegativeInfinity/ToPositiveInfinity semantics remain reachable
    //         only via Truncate/Floor/Ceiling below, which pass 2/3/4 to
    //         InternalRound directly) ---
    {
        Il2CppDecimal d = MakeDec(25, 1);   // 2.5m
        icall_decimal_round(&d, &d, 0, 0);      // ToEven
        ExpectBits("Round(2.5m) == 2m", d, 2, 0, 0, 0);
    }
    {
        Il2CppDecimal d = MakeDec(25, 1);   // 2.5m
        icall_decimal_round(&d, &d, 0, 1);      // AwayFromZero
        ExpectBits("Round(2.5m, AwayFromZero) == 3m", d, 3, 0, 0, 0);
    }
    {
        Il2CppDecimal d = MakeDec(35, 1);   // 3.5m
        icall_decimal_round(&d, &d, 0, 0);
        ExpectBits("Round(3.5m) == 4m", d, 4, 0, 0, 0);
    }
    {
        Il2CppDecimal d = MakeDec(5, 1);    // 0.5m
        icall_decimal_round(&d, &d, 0, 0);
        ExpectBits("Round(0.5m) == 0m (ToEven)", d, 0, 0, 0, 0);
    }
    {
        Il2CppDecimal d = MakeDec(15, 1);   // 1.5m
        icall_decimal_round(&d, &d, 0, 0);
        ExpectBits("Round(1.5m) == 2m", d, 2, 0, 0, 0);
    }
    {
        Il2CppDecimal d = MakeDec(25, 1, true); // -2.5m
        icall_decimal_round(&d, &d, 0, 0);
        ExpectBits("Round(-2.5m) == -2m", d, 2, 0, 0, 0x80000000);
    }
    {
        Il2CppDecimal d = MakeDec(35, 1, true); // -3.5m
        icall_decimal_round(&d, &d, 0, 0);
        ExpectBits("Round(-3.5m) == -4m", d, 4, 0, 0, 0x80000000);
    }
    {
        Il2CppDecimal d = MakeDec(15, 1, true); // -1.5m
        icall_decimal_round(&d, &d, 0, 0);
        ExpectBits("Round(-1.5m) == -2m", d, 2, 0, 0, 0x80000000);
    }
    {
        Il2CppDecimal d = MakeDec(25, 1, true); // -2.5m
        icall_decimal_round(&d, &d, 0, 1);         // AwayFromZero
        ExpectBits("Round(-2.5m, AwayFromZero) == -3m", d, 3, 0, 0, 0x80000000);
    }
    {
        Il2CppDecimal d = MakeDec(15, 1, true); // -1.5m
        icall_decimal_round(&d, &d, 0, 1);
        ExpectBits("Round(-1.5m, AwayFromZero) == -2m", d, 2, 0, 0, 0x80000000);
    }
    {
        Il2CppDecimal d = MakeDec(12345, 4);   // 1.2345m
        icall_decimal_round(&d, &d, 2, 0);
        ExpectBits("Round(1.2345m, 2) == 1.23m", d, 0x7B, 0, 0, 0x00020000);
    }
    {
        Il2CppDecimal d = MakeDec(1235, 3);    // 1.235m
        icall_decimal_round(&d, &d, 2, 1);         // AwayFromZero
        ExpectBits("Round(1.235m, 2, AwayFromZero) == 1.24m", d, 0x7C, 0, 0,
                   0x00020000);
    }
    {
        Il2CppDecimal d = MakeDec(0xFFFFFFFFFFFFFFFFull, 0xFFFFFFFF, 0, false);
        icall_decimal_round(&d, &d, 0, 0);
        ExpectBits("Round(maxvalue, 0) == maxvalue", d, 0xFFFFFFFF, 0xFFFFFFFF,
                   0xFFFFFFFF, 0);
    }
    {
        Il2CppDecimal d = MakeDec(1, 28);      // 1e-28m
        icall_decimal_round(&d, &d, 27, 0);
        ExpectBits("Round(1e-28m, 27) == 0e-27", d, 0, 0, 0, 0x001B0000);
    }
    // D-DR-1 fix: net48 decimal.Round accepts ONLY modes 0 (ToEven) and 1
    // (AwayFromZero); modes 2/3/4 (the netcore ToZero/ToNegativeInfinity/
    // ToPositiveInfinity values) throw ArgumentException -- they are NOT
    // reachable through Round. The netcore-mode semantics stay reachable only
    // through the Truncate/Floor/Ceiling icalls, whose own paths call
    // InternalRound with 2/3/4 directly (verified in section 7 below).
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(27, 1);   // 2.7m
        try
        {
            icall_decimal_round(&d, &d, 0, 2);   // ToZero
        }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.ArgumentException",
                                  std::strlen("System.ArgumentException")) == 0;
        }
        Expect(caught, "Round(mode=2 ToZero) -> ArgumentException (net48)");
    }
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(27, 1, true); // -2.7m
        try
        {
            icall_decimal_round(&d, &d, 0, 3);   // ToNegativeInfinity
        }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.ArgumentException",
                                  std::strlen("System.ArgumentException")) == 0;
        }
        Expect(caught, "Round(mode=3 ToNegativeInfinity) -> ArgumentException (net48)");
    }
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(27, 1);   // 2.7m
        try
        {
            icall_decimal_round(&d, &d, 0, 4);   // ToPositiveInfinity
        }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.ArgumentException",
                                  std::strlen("System.ArgumentException")) == 0;
        }
        Expect(caught, "Round(mode=4 ToPositiveInfinity) -> ArgumentException (net48)");
    }
    // round argument validation
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(15, 1);
        try
        {
            icall_decimal_round(&d, &d, 29, 0);  // decimals > 28
        }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.ArgumentOutOfRangeException",
                                  std::strlen("System.ArgumentOutOfRangeException")) == 0;
        }
        Expect(caught, "Round(decimals=29) -> ArgumentOutOfRangeException");
    }
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(15, 1);
        try
        {
            icall_decimal_round(&d, &d, 0, 7);   // mode outside 0..4
        }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.ArgumentException",
                                  std::strlen("System.ArgumentException")) == 0;
        }
        Expect(caught, "Round(mode=7) -> ArgumentException");
    }

    // --- 7. truncate / floor / ceiling (net48 oracle) ---
    {
        Il2CppDecimal d = MakeDec(27, 1);   // 2.7m
        icall_decimal_truncate(&d, &d);
        ExpectBits("Truncate(2.7m) == 2m", d, 2, 0, 0, 0);
    }
    {
        Il2CppDecimal d = MakeDec(27, 1, true); // -2.7m
        icall_decimal_truncate(&d, &d);
        ExpectBits("Truncate(-2.7m) == -2m", d, 2, 0, 0, 0x80000000);
    }
    {
        Il2CppDecimal d = MakeDec(27, 1);   // 2.7m
        icall_decimal_floor(&d, &d);
        ExpectBits("Floor(2.7m) == 2m", d, 2, 0, 0, 0);
    }
    {
        Il2CppDecimal d = MakeDec(27, 1, true); // -2.7m
        icall_decimal_floor(&d, &d);
        ExpectBits("Floor(-2.7m) == -3m", d, 3, 0, 0, 0x80000000);
    }
    {
        Il2CppDecimal d = MakeDec(27, 1);   // 2.7m
        icall_decimal_ceiling(&d, &d);
        ExpectBits("Ceiling(2.7m) == 3m", d, 3, 0, 0, 0);
    }
    {
        Il2CppDecimal d = MakeDec(27, 1, true); // -2.7m
        icall_decimal_ceiling(&d, &d);
        ExpectBits("Ceiling(-2.7m) == -2m", d, 2, 0, 0, 0x80000000);
    }

    // --- 8. ctors (net48 oracle) ---
    {
        Il2CppDecimal d;
        icall_decimal_ctor_int32(&d, 42);
        ExpectBits("ctor(int 42)", d, 0x2A, 0, 0, 0);
    }
    {
        Il2CppDecimal d;
        icall_decimal_ctor_int32(&d, -42);
        ExpectBits("ctor(int -42)", d, 0x2A, 0, 0, 0x80000000);
    }
    {
        Il2CppDecimal d;
        icall_decimal_ctor_int32(&d, INT32_MIN);
        ExpectBits("ctor(int.MinValue)", d, 0x80000000, 0, 0, 0x80000000);
    }
    {
        Il2CppDecimal d;
        icall_decimal_ctor_int32(&d, INT32_MAX);
        ExpectBits("ctor(int.MaxValue)", d, 0x7FFFFFFF, 0, 0, 0);
    }
    {
        Il2CppDecimal d;
        icall_decimal_ctor_uint32(&d, 4294967295u);
        ExpectBits("ctor(uint.MaxValue)", d, 0xFFFFFFFF, 0, 0, 0);
    }
    {
        Il2CppDecimal d;
        icall_decimal_ctor_int64(&d, 1234567890123456789LL);
        ExpectBits("ctor(long)", d, 0x7DE98115, 0x112210F4, 0, 0);
    }
    {
        Il2CppDecimal d;
        icall_decimal_ctor_int64(&d, -1234567890123456789LL);
        ExpectBits("ctor(long -)", d, 0x7DE98115, 0x112210F4, 0, 0x80000000);
    }
    {
        Il2CppDecimal d;
        icall_decimal_ctor_int64(&d, INT64_MIN);
        ExpectBits("ctor(long.MinValue)", d, 0x00000000, 0x80000000, 0, 0x80000000);
    }
    {
        Il2CppDecimal d;
        icall_decimal_ctor_int64(&d, INT64_MAX);
        ExpectBits("ctor(long.MaxValue)", d, 0xFFFFFFFF, 0x7FFFFFFF, 0, 0);
    }
    {
        Il2CppDecimal d;
        icall_decimal_ctor_uint64(&d, 18446744073709551615ull);
        ExpectBits("ctor(ulong.MaxValue)", d, 0xFFFFFFFF, 0xFFFFFFFF, 0, 0);
    }
    {
        // Literal shape: new decimal(lo=1, mid=2, hi=3, neg=false, scale=4).
        Il2CppDecimal d;
        icall_decimal_ctor_5(&d, 1, 2, 3, false, 4);
        ExpectBits("ctor(1,2,3,false,4)", d, 1, 2, 3, 0x00040000);
    }
    {
        // new decimal(lo=0x80000000, mid=0x7FFFFFFF, hi=0xFFFFFFFF,
        //             neg=true, scale=28) -> -7.9228...e-1 * 10^28 max.
        Il2CppDecimal d;
        icall_decimal_ctor_5(&d, (int32_t)0x80000000, (int32_t)0x7FFFFFFF,
                             (int32_t)0xFFFFFFFF, true, 28);
        ExpectBits("ctor(5-arg max neg, scale 28)", d, 0x80000000, 0x7FFFFFFF,
                   0xFFFFFFFF, 0x801C0000);
    }
    {
        // Negative zero: new decimal(0,0,0,true,0).
        Il2CppDecimal d;
        icall_decimal_ctor_5(&d, 0, 0, 0, true, 0);
        ExpectBits("ctor(0,0,0,true,0) == -0m", d, 0, 0, 0, 0x80000000);
    }
    {
        bool caught = false;
        Il2CppDecimal d;
        try
        {
            icall_decimal_ctor_5(&d, 1, 0, 0, false, 29); // scale > 28
        }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.ArgumentOutOfRangeException",
                                  std::strlen("System.ArgumentOutOfRangeException")) == 0;
        }
        Expect(caught, "ctor(scale=29) -> ArgumentOutOfRangeException");
    }

    // --- 9. truncating conversions (net48 oracle) ---
    {
        Il2CppDecimal d = MakeDec(27, 1);   // 2.7m
        Expect(icall_decimal_to_int32(&d) == 2, "(int)2.7m == 2");
    }
    {
        Il2CppDecimal d = MakeDec(27, 1, true); // -2.7m
        Expect(icall_decimal_to_int32(&d) == -2, "(int)-2.7m == -2");
    }
    {
        Il2CppDecimal d = MakeDec(9999, 4);  // 0.9999m
        Expect(icall_decimal_to_int32(&d) == 0, "(int)0.9999m == 0");
    }
    {
        Il2CppDecimal d = MakeDec(0x80000000ull, 0, true); // -2147483648m
        Expect(icall_decimal_to_int32(&d) == INT32_MIN, "(int)-2147483648m == int.MinValue");
    }
    {
        Il2CppDecimal d = MakeDec(0x7FFFFFFFull, 0, false); // 2147483647m
        Expect(icall_decimal_to_int32(&d) == INT32_MAX, "(int)2147483647m == int.MaxValue");
    }
    {
        Il2CppDecimal d = MakeDec(0x7FFFFFFFFFFFFFFFull, 0, false);
        Expect(icall_decimal_to_int64(&d) == 9223372036854775807LL,
               "(long)9223372036854775807m == long.MaxValue");
    }
    {
        Il2CppDecimal d = MakeDec(0xFFFFFFFFull, 0, false); // 4294967295m
        Expect(icall_decimal_to_uint32(&d) == 4294967295u, "(uint)4294967295m == uint.MaxValue");
    }
    {
        Il2CppDecimal d = MakeDec(0xFFFFFFFFFFFFFFFFull, 0, false);
        Expect(icall_decimal_to_uint64(&d) == 18446744073709551615ull,
               "(ulong)18446744073709551615m == ulong.MaxValue");
    }
    // conversion overflow paths (net48: OverflowException)
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(0x80000000ull, 0, false); // 2147483648m
        try { icall_decimal_to_int32(&d); }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.OverflowException",
                                  std::strlen("System.OverflowException")) == 0;
        }
        Expect(caught, "(int)2147483648m -> OverflowException");
    }
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(0x80000001ull, 0, true); // -2147483649m
        try { icall_decimal_to_int32(&d); }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.OverflowException",
                                  std::strlen("System.OverflowException")) == 0;
        }
        Expect(caught, "(int)-2147483649m -> OverflowException");
    }
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(0x8000000000000000ull, 0, false);
        try { icall_decimal_to_int64(&d); }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.OverflowException",
                                  std::strlen("System.OverflowException")) == 0;
        }
        Expect(caught, "(long)9223372036854775808m -> OverflowException");
    }
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(1, 0, true); // -1m
        try { icall_decimal_to_uint32(&d); }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.OverflowException",
                                  std::strlen("System.OverflowException")) == 0;
        }
        Expect(caught, "(uint)-1m -> OverflowException");
    }
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(0x100000000ull, 0, false); // 4294967296m
        try { icall_decimal_to_uint32(&d); }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.OverflowException",
                                  std::strlen("System.OverflowException")) == 0;
        }
        Expect(caught, "(uint)4294967296m -> OverflowException");
    }
    {
        bool caught = false;
        Il2CppDecimal d = MakeDec(1, 0, true); // -1m
        try { icall_decimal_to_uint64(&d); }
        catch (const il2cpp::DotNetException& e)
        {
            caught = std::strncmp(e.type_name(), "System.OverflowException",
                                  std::strlen("System.OverflowException")) == 0;
        }
        Expect(caught, "(ulong)-1m -> OverflowException");
    }

    // --- 10. GetHashCode: scale-canonical hashing (1m == 1.00m), zero == 0 ---
    {
        Il2CppDecimal d1 = MakeDec(1, 0);
        Il2CppDecimal d2 = MakeDec(100, 2);
        Expect(icall_decimal_get_hash_code(&d1) == icall_decimal_get_hash_code(&d2),
               "hash(1m) == hash(1.00m)");
    }
    {
        Il2CppDecimal d = MakeDec(0, 0);
        Expect(icall_decimal_get_hash_code(&d) == 0, "hash(0m) == 0");
    }
    {
        Il2CppDecimal d1 = MakeDec(1, 0);
        Il2CppDecimal d2 = MakeDec(1, 0, true);
        Expect(icall_decimal_get_hash_code(&d1) != icall_decimal_get_hash_code(&d2),
               "hash(1m) != hash(-1m)");
    }

    // --- 11. overflow / divide-by-zero exception paths (net48 types) ---
    ExpectThrows("maxvalue + 1m -> OverflowException", "System.OverflowException",
                 [](Il2CppDecimal& x, Il2CppDecimal& y) {
                     x = MakeDec(0xFFFFFFFFFFFFFFFFull, 0xFFFFFFFF, 0, false);
                     y = MakeDec(1, 0);
                     icall_decimal_add(&x, &x, &y);
                 });
    ExpectThrows("maxvalue * 2m -> OverflowException", "System.OverflowException",
                 [](Il2CppDecimal& x, Il2CppDecimal& y) {
                     x = MakeDec(0xFFFFFFFFFFFFFFFFull, 0xFFFFFFFF, 0, false);
                     y = MakeDec(2, 0);
                     icall_decimal_mul(&x, &x, &y);
                 });
    ExpectThrows("1m / 0m -> DivideByZeroException", "System.DivideByZeroException",
                 [](Il2CppDecimal& x, Il2CppDecimal& y) {
                     x = MakeDec(1, 0);
                     y = MakeDec(0, 0);
                     icall_decimal_div(&x, &x, &y);
                 });
    ExpectThrows("1m % 0m -> DivideByZeroException", "System.DivideByZeroException",
                 [](Il2CppDecimal& x, Il2CppDecimal& y) {
                     x = MakeDec(1, 0);
                     y = MakeDec(0, 0);
                     icall_decimal_rem(&x, &x, &y);
                 });

    // --- 12. strict T3 emitter shape (MethodMap.Decimal.cs:23-35): the
    //         AssignStmt "dec" case emits fn(resultSlot, args...) with a
    //         FRESH result slot -- inputs are const and must never be
    //         mutated. (The aliasing shape fn(&a, &a, &b) is exercised by
    //         every converted block above.)
    {
        Il2CppDecimal a = MakeDec(1, 1);   // 0.1m
        Il2CppDecimal b = MakeDec(2, 1);   // 0.2m
        Il2CppDecimal t = MakeDec(0, 0);
        icall_decimal_add(&t, &a, &b);
        ExpectBits("T3 add: fn(t,a,b) == 0.3m", t, 3, 0, 0, 0x00010000);
        ExpectBits("T3 add: input a untouched", a, 1, 0, 0, 0x00010000);
        ExpectBits("T3 add: input b untouched", b, 2, 0, 0, 0x00010000);
    }
    {
        Il2CppDecimal a = MakeDec(15, 1);  // 1.5m
        Il2CppDecimal b = MakeDec(2, 0);   // 2m
        Il2CppDecimal t = MakeDec(0, 0);
        icall_decimal_mul(&t, &a, &b);
        ExpectBits("T3 mul: fn(t,a,b) == 3.0m", t, 0x1E, 0, 0, 0x00010000);
        ExpectBits("T3 mul: input a untouched", a, 15, 0, 0, 0x00010000);
        ExpectBits("T3 mul: input b untouched", b, 2, 0, 0, 0);
    }
    {
        Il2CppDecimal a = MakeDec(100, 0); // 100m
        Il2CppDecimal b = MakeDec(7, 0);   // 7m
        Il2CppDecimal t = MakeDec(0, 0);
        icall_decimal_div(&t, &a, &b);
        ExpectBits("T3 div: fn(t,a,b) == 100m/7m", t, 0xCDB6DB6E, 0x3434DED3,
                   0x2E28DDAB, 0x001B0000);
        ExpectBits("T3 div: input a untouched", a, 100, 0, 0, 0);
        ExpectBits("T3 div: input b untouched", b, 7, 0, 0, 0);
    }
    {
        Il2CppDecimal a = MakeDec(10, 0);  // 10m
        Il2CppDecimal b = MakeDec(3, 0);   // 3m
        Il2CppDecimal t = MakeDec(0, 0);
        icall_decimal_rem(&t, &a, &b);
        ExpectBits("T3 rem: fn(t,a,b) == 1m", t, 1, 0, 0, 0);
        ExpectBits("T3 rem: input a untouched", a, 10, 0, 0, 0);
        ExpectBits("T3 rem: input b untouched", b, 3, 0, 0, 0);
    }
    {
        Il2CppDecimal d = MakeDec(15, 1, true); // -1.5m
        Il2CppDecimal t = MakeDec(0, 0);
        icall_decimal_negate(&t, &d);
        ExpectBits("T3 negate: fn(t,d) == 1.5m", t, 15, 0, 0, 0x00010000);
        ExpectBits("T3 negate: input d untouched", d, 15, 0, 0, 0x80010000);
    }
    {
        Il2CppDecimal d = MakeDec(25, 1);  // 2.5m
        Il2CppDecimal t = MakeDec(0, 0);
        icall_decimal_round(&t, &d, 0, 0); // ToEven
        ExpectBits("T3 round: fn(t,d,0,0) == 2m", t, 2, 0, 0, 0);
        ExpectBits("T3 round: input d untouched", d, 25, 0, 0, 0x00010000);
    }
    {
        Il2CppDecimal d = MakeDec(27, 1, true); // -2.7m
        Il2CppDecimal t = MakeDec(0, 0);
        icall_decimal_truncate(&t, &d);
        ExpectBits("T3 truncate: fn(t,d) == -2m", t, 2, 0, 0, 0x80000000);
        icall_decimal_floor(&t, &d);
        ExpectBits("T3 floor: fn(t,d) == -3m", t, 3, 0, 0, 0x80000000);
        icall_decimal_ceiling(&t, &d);
        ExpectBits("T3 ceiling: fn(t,d) == -2m", t, 2, 0, 0, 0x80000000);
        ExpectBits("T3 trunc/floor/ceil: input d untouched", d, 27, 0, 0,
                   0x80010000);
    }

    if (g_failures == 0)
    {
        std::printf("all decimal arithmetic tests passed\n");
        return 0;
    }
    std::printf("%d decimal arithmetic test(s) failed\n", g_failures);
    return 1;
}
